    catch {
      try { this._audit('stream_refused', principal, origin, { repoId: grant.repoId, reason: 'snapshot_unavailable' }); }
      catch { return response(503, 'temporarily_unavailable'); }
      return response(503, 'temporarily_unavailable');
    }
