function fixture(overrides = {}) {
  const calls = [];
  const coordinator = {
    async spawn(harness, brief, opts) { calls.push({ op: 'spawn', harness, brief, opts }); return { id: 'w-1', taskId: opts.taskId, fence: 1 }; },
    list() { calls.push({ op: 'list' }); return [{ id: 'w-1', fence: 1, status: 'working' }]; },
