  });
  const command = (id) => ({ schemaVersion: 1, commandId: id, idempotencyKey: id, command: 'list', args: {}, repoId: 'repo-a', origin: 'https://control.example.test' });
  const req = request({ cookie: `__Host-baton_session=${issued.token}` });
